    if (nodes == null) throw new ArgumentNullException(nameof(nodes));
    var clusters = new List<MarkerSemanticCluster>(nodes.Count);
    var physicalKeys = new List<long>();
    var members = new HashSet<long>();
    for (var i = 0; i < nodes.Count; i++)
